// ─── timeline: section/line lookups, subtitles, header, transitions ─────────
// window.TL is generated by tools/build_timeline.py from the synthesized voice:
//   { dur, sections: [{ id, title, t0, t1, lines: [{ sub, t0, t1, ch: [start time per char] }] }] }

const SEC = {};
const SCENES = {};
function initTimeline() {
  TL.sections.forEach((s, i) => {
    s.index = i;
    // start time of line i (negative i counts from the end)
    s.L = (i) => s.lines[(i + s.lines.length) % s.lines.length].t0;
    s.E = (i) => s.lines[(i + s.lines.length) % s.lines.length].t1;
    // time the n-th occurrence of `str` starts being spoken in line i
    s.at = (i, str, n = 0) => {
      const ln = s.lines[(i + s.lines.length) % s.lines.length];
      let p = -1; for (let k = 0; k <= n; k++) p = ln.sub.indexOf(str, p + 1);
      return p < 0 ? ln.t0 : ln.ch[p];
    };
    // time the given substring finishes
    s.after = (i, str) => {
      const ln = s.lines[(i + s.lines.length) % s.lines.length];
      const p = ln.sub.indexOf(str); if (p < 0) return ln.t1;
      const q = p + str.length; return q < ln.ch.length ? ln.ch[q] : ln.t1;
    };
    SEC[s.id] = s;
  });
}

const ACCENT = {
  intro: '#ff3b6b', 'ksm-voice': '#ff5522', 'ksm-orbit': '#ff5522', ars: '#aa66dd', otae: '#0077dd',
  moca: '#00ccaa', ran: '#ee0022', roselia: '#5a3fb8', pasupare: '#ff88bb', outro: '#ff3b6b',
};
const SEC_LABEL = {
  intro: ['00', '开场'], 'ksm-voice': ['01', 'ksm · 声音'], 'ksm-orbit': ['02', 'ksm · 距离'], ars: ['03', 'ars · 傲娇永动机'],
  otae: ['04', 'otae · 电波克傲娇'], moca: ['05', '摩卡 · 审美暴击'], ran: ['06', '兰 · 反差'], roselia: ['07', '萝团'],
  pasupare: ['08', 'Pastel*Palettes'], outro: ['', '下期见'],
};
const SEC_LOGO = { 'ksm-voice': 'logo1', 'ksm-orbit': 'logo1', ars: 'logo1', otae: 'logo1', moca: 'logo2', ran: 'logo2', roselia: 'logo5', pasupare: 'logo4' };

// names get their character colour in subtitles
const NAME_COLORS = [
  ['ksm', '#ff7a45'], ['ars', '#c48af0'], ['otae', '#3aa0ff'], ['摩卡', '#19e0bf'], ['兰', '#ff4058'],
  ['ykn', '#c45ccf'], ['sayo', '#1fc6d8'], ['lisa', '#ff6a3d'], ['maya', '#9be08a'], ['伊芙', '#d9b8ff'],
  ['千圣', '#ffe68a'], ['初华', '#ffd36b'], ['峰月律', '#8fc9ff'], ['萝团', '#9f86ff'], ['Pastel*Palettes', '#ff9fc8'],
  ['前へススメ!', '#ffcf3f'],
];

function sectionAt(t) {
  const S = TL.sections; for (let i = S.length - 1; i >= 0; i--) if (t >= S[i].t0) return S[i]; return S[0];
}
function lineAt(t) {
  for (const s of TL.sections) for (let i = 0; i < s.lines.length; i++) {
    const l = s.lines[i], next = s.lines[i + 1];
    const end = Math.min(l.t1 + 0.45, next ? next.t0 : s.t1);
    if (t >= l.t0 - 0.05 && t < end) return l;
  }
  return null;
}

// split a subtitle into ≤2 balanced rows at punctuation
function splitSub(s) {
  const max = 15;
  if (s.length <= max) return [s];
  let best = -1, bestScore = 1e9;
  for (let i = 4; i < s.length - 3; i++) {
    if ('，、：；。！？ '.includes(s[i])) {
      const a = i + 1, score = Math.abs(a - (s.length - a));
      if (score < bestScore) { bestScore = score; best = a; }
    }
  }
  if (best < 0 || Math.max(best, s.length - best) > max + 4) best = Math.ceil(s.length / 2);
  return [s.slice(0, best), s.slice(best)];
}
// runs of [text, colour] for name highlighting
function colorRuns(s) {
  const runs = []; let i = 0;
  while (i < s.length) {
    let hit = null;
    for (const [n, col] of NAME_COLORS) if (s.startsWith(n, i)) { hit = [n, col]; break; }
    if (hit) { runs.push(hit); i += hit[0].length; }
    else { if (runs.length && runs[runs.length - 1][1] === null) runs[runs.length - 1][0] += s[i]; else runs.push([s[i], null]); i++; }
  }
  return runs;
}

function drawSubtitle(c, t) {
  const l = lineAt(t); if (!l) return;
  const k = ez(t, l.t0 - 0.05, 0.16);
  const rows = splitSub(l.sub.replace(/[，。]$/, ''));
  // fit the widest row into 980 px
  let size = rows.some((r) => r.length > 13) ? 60 : 66;
  const widest = Math.max(...rows.map((r) => measure(c, r, size, F.black)));
  if (widest > 980) size = Math.floor(size * 980 / widest);
  const lh = size * 1.32;
  const y0 = 1500 - ((rows.length - 1) * lh) / 2;
  const acc = ACCENT[sectionAt(t).id] || '#ff3b6b';
  c.save(); c.globalAlpha = k;
  rows.forEach((r, ri) => {
    const runs = colorRuns(r);
    const widths = runs.map(([s]) => measure(c, s, size, F.black));
    let x = W / 2 - widths.reduce((a, b) => a + b, 0) / 2;
    const y = y0 + ri * lh + (1 - k) * 18;
    runs.forEach(([s, col], i) => {
      txt(c, s, x, y + 7, { size, fam: F.black, color: acc, stroke: acc, sw: 16, align: 'left' });
      txt(c, s, x, y, { size, fam: F.black, color: col || '#fff', stroke: '#16131f', sw: 13, align: 'left' });
      x += widths[i];
    });
  });
  c.restore();
}

function drawHeader(c, t) {
  const s = sectionAt(t); const lab = SEC_LABEL[s.id]; if (!lab || s.id === 'intro' || s.id === 'outro') return;
  const k = ez(t, s.t0 + 0.15, 0.5, ease.back);
  const acc = ACCENT[s.id];
  c.save(); c.translate(0, lerp(-200, 0, k));
  c.fillStyle = 'rgba(20,16,30,.25)'; rrect(c, 46, 84, 988, 128, 40); c.fill();
  c.fillStyle = '#fffaf2'; rrect(c, 40, 74, 988, 128, 40); c.fill();
  c.fillStyle = acc; rrect(c, 40, 74, 150, 128, 40); c.fill(); c.fillRect(150, 74, 40, 128);
  txt(c, lab[0], 115, 140, { size: 74, fam: F.round, color: '#fff' });
  txt(c, lab[1], 222, 140, { size: 58, fam: F.black, color: '#1e1a2b', align: 'left' });
  const lg = SEC_LOGO[s.id]; if (lg) img(c, lg, 935, 138, 84, { alpha: 0.95 });
  // progress: one tick per numbered section
  const ids = TL.sections.filter((x) => SEC_LABEL[x.id] && SEC_LABEL[x.id][0] && x.id !== 'intro').map((x) => x.id);
  const cur = ids.indexOf(s.id);
  ids.forEach((id, i) => {
    const x = 70 + i * ((940 - 20) / ids.length);
    c.fillStyle = i < cur ? hexA(ACCENT[id], 0.9) : i === cur ? acc : 'rgba(255,255,255,.55)';
    rrect(c, x, 222, (940 - 20) / ids.length - 12, 10, 5); c.fill();
    if (i === cur) { const p = clamp((t - s.t0) / (s.t1 - s.t0)); c.fillStyle = '#fff'; rrect(c, x, 222, ((940 - 20) / ids.length - 12) * p, 10, 5); c.fill(); }
  });
  c.restore();
}

function drawFooter(c, t) {
  txt(c, '邦多利角色个人向点评 · 上', W / 2, 1838, { size: 30, fam: F.bold, color: 'rgba(255,255,255,.7)', stroke: 'rgba(0,0,0,.25)', sw: 6, ls: 4 });
}

// position (seconds) inside 前へススメ at time t, from the music plan
function songPos(t) {
  let pos = 0;
  for (const m of TL.music) if (m.track === 'maesusume' && t >= m.t0) pos = m.src + (t - m.t0);
  return pos;
}
